CREATE TABLE asaas_runtime_config(singleton INTEGER PRIMARY KEY CHECK(singleton=1),account_id TEXT NOT NULL,org_id TEXT NOT NULL REFERENCES organizations(id));
CREATE TABLE asaas_customer_intents(user_id TEXT PRIMARY KEY REFERENCES users(id),org_id TEXT NOT NULL REFERENCES organizations(id),reference TEXT NOT NULL UNIQUE,fingerprint TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('creating','unknown','ready')),customer_id TEXT UNIQUE);
CREATE UNIQUE INDEX asaas_buyer_user ON commerce_buyers(user_id) WHERE user_id IS NOT NULL;
CREATE TABLE asaas_student_sources(student_id TEXT PRIMARY KEY REFERENCES students(id),buyer_id TEXT NOT NULL UNIQUE REFERENCES commerce_buyers(id));
CREATE TABLE asaas_protocol_orders(order_id TEXT PRIMARY KEY REFERENCES commerce_orders(id),student_id TEXT NOT NULL REFERENCES students(id),plan_id TEXT UNIQUE REFERENCES plans(id),nutrition_plan_id TEXT UNIQUE REFERENCES nutrition_plans(id),CHECK((plan_id IS NULL) <> (nutrition_plan_id IS NULL)));
CREATE TABLE asaas_service_periods(order_id TEXT PRIMARY KEY REFERENCES commerce_orders(id),student_id TEXT NOT NULL REFERENCES students(id),plan_id TEXT REFERENCES plans(id),nutrition_plan_id TEXT REFERENCES nutrition_plans(id),actor_id TEXT NOT NULL REFERENCES users(id),released_at BIGINT NOT NULL,starts_at BIGINT NOT NULL,ends_at BIGINT NOT NULL CHECK(ends_at>starts_at),CHECK((plan_id IS NULL) <> (nutrition_plan_id IS NULL)));
CREATE TABLE asaas_purchase_requests(order_id TEXT NOT NULL REFERENCES commerce_orders(id),kind TEXT NOT NULL CHECK(kind IN ('refund','cancel-purchase')),created_at BIGINT NOT NULL,window_status TEXT NOT NULL,PRIMARY KEY(order_id,kind));
